INSERT IGNORE INTO deal_tag (deal_id, tag_id)
SELECT d.id, t.id
FROM deal d
JOIN tag t ON t.id IN

  #{tagId}

WHERE d.workspace_id = #{workspaceId} AND d.id = #{dealId} AND t.workspace_id = #{workspaceId}

INSERT INTO deal_person (deal_id, person_id, role)
SELECT d.id, #{personId}, #{role}
FROM deal d
WHERE d.workspace_id = #{workspaceId} AND d.id = #{dealId}
ON DUPLICATE KEY UPDATE role = VALUES(role)

mapper.update:
UPDATE deal_person dp
JOIN deal d ON d.id = dp.deal_id
SET dp.role = #{role}
WHERE d.workspace_id = #{workspaceId}
  AND dp.deal_id = #{dealId}
  AND dp.person_id = #{personId}

mapper.delete:
